public class Ex03 {
    static class Dep { String name = "dep"; }
    // 构造器注入：final 字段可注入，构造后不可变
    static class ByConstructor {
        private final Dep dep;
        ByConstructor(Dep d) { this.dep = d; }
        String go() { return dep.name; }
    }
    // Setter 注入：字段可变，可重复赋值
    static class BySetter {
        private Dep dep;
        void setDep(Dep d) { this.dep = d; }
        String go() { return dep.name; }
    }
    public static void main(String[] args) {
        Dep d = new Dep();
        ByConstructor c = new ByConstructor(d);
        BySetter s = new BySetter();
        s.setDep(d);
        System.out.println("ctor immutable: " + c.go());
        Dep another = new Dep();
        another.name = "dep2";
        s.setDep(another);
        System.out.println("setter reassignable: " + s.go());
    }
}
